head.script:
scwin.trigger1_onclick = function(e) {
    count++;
    widgetContainer1.addWidgets({
        id: "widget" + count,
        title: "위젯" + count,
        src: "widget_WP-3090_(WSQ-2452)_1_subContainer.xml",
        scope: true,
        x: 0,
        y: 0,
        unitWidth: 1,
        unitHeight: 1
    });
};
scwin.checkValue = function(id) {
    if (WebSquare.wUnit.getDomById($p.id + id)) {
        return true;
    }
    return false
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. TestData 1번의 _mainContainer.xml을 실행 후 'addWidget'버튼을 클릭한다.
    //1. Run TestData # _mainContainer.xml and click the 'addWidget' button.
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify  1. 위젯컨테이너안에 서브위젯이 생성되고 'widget1'이 보여진다.(정상)
    //1. A sub-widget is created in the widget container and 'widget1' is displayed. (Normal)
    WebSquare.wUnit.addCommand("assert", "scwin.checkValue('widgetContainer1_widget1')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#widgetContainer1_widget1_content_wq_uuid_13').text() == 'widget1'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.count = 0;
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 13-Feb-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
